RAPPORT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "rapports")

def _rapport_html(which=None):
    """Page HTML des rapports quotidiens (accessible via favori : /rapport).
    Liste les rapports disponibles et affiche le plus récent, sans ouvrir de fichier."""
    import glob, html as _h
    files = sorted(glob.glob(os.path.join(RAPPORT_DIR, "rapport_*.txt")), reverse=True)
    if which:                                     # sélection dans la liste déroulante
        safe = os.path.basename(which)            # jamais de chemin fourni par l'URL
        cand = os.path.join(RAPPORT_DIR, safe)
        if cand in files:
            files = [cand] + [f for f in files if f != cand]
    if not files:
        body = ("<p class='vide'>Aucun rapport pour l'instant.<br>Lance <code>py daily.py</code> "
                "(ou attends la t\u00e2che quotidienne) pour en g\u00e9n\u00e9rer un.</p>")
        opts = ""
    else:
        with open(files[0], encoding="utf-8") as f:
            body = "<pre id='txt'>" + _h.escape(f.read()) + "</pre>"
        opts = "".join(
            f"<option value='{os.path.basename(p)}'>{os.path.basename(p)[8:-4]}</option>"
            for p in files[:60])
    return """<!doctype html><html lang="fr"><head><meta charset="utf-8">
<title>Rapports \u2014 Flow Engine</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
 body{background:#0b0d12;color:#e8e6e3;font-family:ui-monospace,Menlo,Consolas,monospace;margin:0;padding:22px;}
 .bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:16px;}
 h1{font-size:16px;margin:0;letter-spacing:.5px;}
 a,select,button{background:#12151d;color:#e8e6e3;border:1px solid #262b36;border-radius:7px;
   padding:6px 11px;font-family:inherit;font-size:12px;text-decoration:none;cursor:pointer;}
 a:hover,button:hover{border-color:#3a3f4b;}
 pre{background:#101319;border:1px solid #1e222c;border-radius:10px;padding:18px;
   white-space:pre-wrap;line-height:1.55;font-size:12.5px;max-width:1000px;}
 .vide{color:#8b949e;}
 code{background:#1a1e27;padding:2px 6px;border-radius:4px;}
</style></head><body>
<div class="bar">
  <h1>\U0001F4C8 RAPPORTS QUOTIDIENS</h1>
  <a href="/">\u2190 Dashboard</a>
  """ + (f"<select onchange=\"location='/rapport?f='+this.value\">{opts}</select>" if opts else "") + """
  <button onclick="navigator.clipboard.writeText(document.getElementById('txt').innerText).then(()=>{this.textContent='\u2713 Copi\u00e9 !';setTimeout(()=>this.textContent='\U0001F4CB Copier pour Claude',1500);})">\U0001F4CB Copier pour Claude</button>
</div>
""" + body + """
</body></html>"""


def _backtest_html(asset="BTC"):
    """Page /backtest : lance le backtest sur l'actif demande et rend le resultat."""
    import io, contextlib, html as _h
    buf = io.StringIO()
    try:
        import importlib, backtest as bt
        importlib.reload(bt)
        old = sys.argv
        sys.argv = ["backtest.py", asset, "mensuel"]
        try:
            with contextlib.redirect_stdout(buf):
                bt.main()
        finally:
            sys.argv = old
        txt = buf.getvalue()
    except Exception as e:
        txt = (f"Backtest indisponible : {e}\n\n"
               "Verifie que backtest.py est bien dans le meme dossier.")
    try:
        ids = sorted(fe.ASSETS.keys())
    except Exception:
        ids = ["BTC", "ETH"]
    opts = "".join(f"<option value='{i}'{' selected' if i == asset else ''}>{i}</option>"
                   for i in ids)
    return """<!doctype html><html lang="fr"><head><meta charset="utf-8">
<title>Backtest \u2014 Flow Engine</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
 body{background:#0b0d12;color:#e8e6e3;font-family:ui-monospace,Menlo,Consolas,monospace;margin:0;padding:22px;}
 .bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:16px;}
 h1{font-size:16px;margin:0;letter-spacing:.5px;}
 a,select,button{background:#12151d;color:#e8e6e3;border:1px solid #262b36;border-radius:7px;
   padding:6px 11px;font-family:inherit;font-size:12px;text-decoration:none;cursor:pointer;}
 a:hover,button:hover{border-color:#3a3f4b;}
 pre{background:#101319;border:1px solid #1e222c;border-radius:10px;padding:18px;
   white-space:pre-wrap;line-height:1.55;font-size:12.5px;max-width:1050px;}
 .note{color:#8b949e;font-size:11.5px;max-width:1050px;margin-top:12px;line-height:1.6;}
</style></head><body>
<div class="bar">
  <h1>\U0001F9EA BACKTEST</h1>
  <a href="/">\u2190 Dashboard</a>
  <a href="/rapport">\U0001F4C8 Rapports</a>
  <select onchange="location='/backtest?a='+this.value">""" + opts + """</select>
  <button onclick="navigator.clipboard.writeText(document.getElementById('txt').innerText).then(()=>{this.textContent='\u2713 Copie !';setTimeout(()=>this.textContent='\U0001F4CB Copier pour Claude',1500);})">\U0001F4CB Copier pour Claude</button>
</div>
<pre id="txt">""" + _h.escape(txt) + """</pre>
<div class="note">Ce backtest compare chaque indicateur du jour J au mouvement de prix J\u2192J+1.
Tout resultat marque <b>NON FIABLE</b> repose sur trop peu d'observations pour conclure :
sur 15 cas, un ecart de 15 points releve du hasard. Il faut viser 60 a 100 jours de collecte
propre avant de tirer la moindre conclusion.</div>
</body></html>"""

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):  # silence les logs HTTP
        pass

    def _send(self, code, body, ctype):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        path = self.path.split("?")[0]
        if path == "/" or path == "/index.html":
            if os.path.exists("dashboard.html"):
                with open("dashboard.html", "rb") as f:
                    self._send(200, f.read(), "text/html; charset=utf-8")
            else:
                self._send(200, base64.b64decode(HTML_B64), "text/html; charset=utf-8")
            return
        if path == "/backtest":
            qs = self.path.split("?", 1)[1] if "?" in self.path else ""
            a = "BTC"
            for kv in qs.split("&"):
                if kv.startswith("a="):
                    a = kv[2:].upper()[:12]
            self._send(200, _backtest_html(a).encode("utf-8"), "text/html; charset=utf-8")
            return
        if path == "/rapport" or path == "/rapports":
            qs = self.path.split("?", 1)[1] if "?" in self.path else ""
            sel = None
            for kv in qs.split("&"):
                if kv.startswith("f="):
                    sel = kv[2:]
            self._send(200, _rapport_html(sel).encode("utf-8"),
                       "text/html; charset=utf-8")
            return
        if path == "/api/assets":
            body = json.dumps([{"id": k, "label": v["label"],
                                "cat": v.get("cat", "macro"), "group": v.get("group", ""),
                                "ticker": (v["cboe"].lstrip("_") if v.get("source") == "cboe" and v.get("cboe") else k)}
                               for k, v in fe.ASSETS.items()])
            self._send(200, body.encode(), "application/json")
            return
        if path.startswith("/api/"):
            import urllib.parse
            asset = urllib.parse.unquote(path.split("/api/")[1]).upper()
            qs = urllib.parse.parse_qs(self.path.split("?")[1]) if "?" in self.path else {}
            dte = qs.get("dte", [None])[0]
            fresh = qs.get("fresh", [None])[0]
            sign = qs.get("sign", [None])[0]              # "fixed" | "adaptive" | None(=réglage global)
            if sign not in ("fixed", "adaptive"):
                sign = None
            ck = f"{asset}:{dte}:{sign}"                  # le mode fait partie de la clé de cache
            now = time.time()
            if not fresh and ck in _CACHE and now - _CACHE[ck][0] < _TTL:
                self._send(200, _CACHE[ck][1], "application/json")
                return
            try:
                data = fe.analyse(asset, dte_days=dte, sign_mode=sign)
                body = json.dumps(data, default=str).encode()
                _CACHE[ck] = (now, body)
                self._send(200, body, "application/json")
            except Exception as e:
                traceback.print_exc()
                self._send(500, json.dumps({"error": str(e)}).encode(), "application/json")
            return
        self._send(404, b"not found", "text/plain")


def local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "127.0.0.1"


def open_browser():
    time.sleep(1.2)
    try:
        webbrowser.open(f"http://localhost:{PORT}")
    except Exception:
        pass


if __name__ == "__main__":
    ip = local_ip()
    print("\n  Flow Engine - dashboard")
    print(f"  Sur ce PC          : http://localhost:{PORT}")
    print(f"  Sur le reseau local: http://{ip}:{PORT}   (tel, autre PC du meme wifi)")
    print("  (Chrome s'ouvre tout seul. Laisse cette fenetre OUVERTE.)\n")
    threading.Thread(target=open_browser, daemon=True).start()
    try:
        ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()
    except OSError as e:
        print(f"[ERREUR] Port {PORT} deja utilise ou bloque : {e}")
        input("Appuie sur Entree pour fermer...")
